draw(Circle((0,0),4));
draw((-5,0)--(5,0),dashed);
draw(F[1]--P--F[2]);
draw(rightanglemark(F[1],P,F[2],15));

dot("$F_1$", F[1], SW);
dot("$F_2$", F[2], SE);
dot("$P$", P, NW);
